{"path":"config_parser.py","content":"import json

def parse_config_with_defaults(config_path, defaults, required_fields=None):
    if required_fields is None:
        required_fields = []

    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        raise ValueError(f"Config file not found: {config_path}")
    except json.JSONDecodeError:
        raise ValueError(f"Invalid JSON in config file: {config_path}")

    def _merge_and_validate(config, defaults, path=''):
        merged = {}

        # Check all required fields are present
        for field in required_fields:
            if field not in config and field not in defaults:
                raise ValueError(f"Missing required field: {path}{field}")

        # Get all unique keys from both dicts
        all_keys = set(config.keys()).union(set(defaults.keys()))

        for key in all_keys:
            current_path = f'{path}{key}.' if path else f'{key}.'

            # Config takes precedence
            if key in config and key in defaults:
                if isinstance(config[key], dict) and isinstance(defaults[key], dict):
                    merged[key] = _merge_and_validate(config[key], defaults[key], current_path)
                else:
                    merged[key] = config[key]
            elif key in config:
                merged[key] = config[key]
            else:
                merged[key] = defaults[key]

        return merged

    return _merge_and_validate(config, defaults)
"}

